package com.lifeorganizer;
import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import java.sql.*;
public class SearchView extends VBox {
 public SearchView(int userId){setPadding(new Insets(20));setSpacing(12);Label h=new Label("Global Search");h.setStyle("-fx-font-size:25px;-fx-font-weight:bold;");TextField q=new TextField();q.setPromptText("Search tasks, bills, expenses, groceries, medicines, documents and events");TextArea out=new TextArea();out.setEditable(false);Button go=new Button("Search");go.setOnAction(e->search(userId,q.getText(),out));q.setOnAction(e->search(userId,q.getText(),out));getChildren().addAll(h,q,go,out);}
 private void search(int id,String term,TextArea out){if(term==null||term.isBlank()){out.setText("Enter a search term.");return;}StringBuilder b=new StringBuilder();String[][] tables={{"tasks","task_name","deadline"},{"bills","bill_name","due_date"},{"expenses","category","expense_date"},{"groceries","item_name","purchased_status"},{"medicines","medicine_name","reminder_time"},{"documents","document_name","category"},{"calendar_events","event_title","event_date"}};try(Connection c=Db.connect()){for(String[]t:tables){String idColumn=t[0].equals("groceries")?"grocery_id":t[0].substring(0,t[0].length()-1)+"_id";String sql="SELECT "+idColumn+","+t[1]+","+t[2]+" FROM "+t[0]+" WHERE user_id=? AND (CAST("+t[1]+" AS CHAR) LIKE ? OR CAST("+t[2]+" AS CHAR) LIKE ?) LIMIT 50";if(t[0].equals("calendar_events"))sql= "SELECT event_id,event_title,event_date FROM calendar_events WHERE user_id=? AND (event_title LIKE ? OR CAST(event_date AS CHAR) LIKE ?) LIMIT 50";try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,id);p.setString(2,"%"+term+"%");p.setString(3,"%"+term+"%");try(ResultSet r=p.executeQuery()){while(r.next())b.append(t[0].toUpperCase()).append(" #").append(r.getString(1)).append(" | ").append(r.getString(2)).append(" | ").append(r.getString(3)).append('\n');}}}out.setText(b.length()==0?"No matching records found.":b.toString());}catch(Exception e){out.setText("Search error: "+e.getMessage());}}
}
